module adder_16bit (
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout
);

    wire [15:0] c;

    adder_8bit a1 (
        .a(a[7:0]),
        .b(b[7:0]),
        .cin(cin),
        .sum(sum[7:0]),
        .cout(c[7])
    );

    adder_8bit a2 (
        .a(a[15:8]),
        .b(b[15:8]),
        .cin(c[7]),
        .sum(sum[15:8]),
        .cout(c[15])
    );

    assign cout = c[15];

endmodule
